"""Per-feature macroscopic extent review of the actual BP/Z source meshes.

Manual decisions below follow visual review of all 96 saved views. A surface
marker is NOT used to infer extent. Re-run the renderer before reviewing changed
meshes; the manifest hashes deliberately prevent silently reusing old decisions.
"""
import hashlib
import json
from collections import Counter
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
def read(name): return json.loads((ROOT/name).read_text(encoding='utf-8'))
def sha(name): return hashlib.sha256((ROOT/name).read_bytes()).hexdigest()

