CRITERIA = {
'surface':'Вся названная макроскопическая поверхность до анатомических границ, доступная с нескольких направлений; отдельные мелкие образования учитываются своими строками.',
'part':'Вся наружная макроформа названной костной части, её свободные границы и переходы к соседним частям; внутренние образования принимаются отдельно, а не автоматически.',
'plate':'Вся пластинка от прикреплённого до свободного края, оба конца и обе поверхности; не только один участок поверхности.',
'edge':'Весь названный край между его анатомическими концами, включая переходы и читаемый макроконтур.',
'process':'Весь отросток от основания до свободной верхушки со сторон, позволяющих оценить его форму.',
'ridge':'Весь гребень или линия от начала до окончания и переходы в окружающую поверхность.',
'eminence':'Целое возвышение: основание, вершина и переходы в окружающую поверхность; общая выпуклость без различимого рельефа недостаточна.',
'fossa':'Полная впадина с дном и всеми макроскопическими границами; один локальный провал сетки недостаточен.',
'notch':'Полный контур вырезки, её дно и оба перехода к соседним краям.',
'groove':'Вся борозда от начала до окончания с дном и двумя ограничивающими краями в пределах данной кости.',
'grooves':'Полная прослеживаемая группа борозд в пределах данной кости, включая видимые ветви и их окончания.',
'opening':'Полный костный край и просвет отверстия; для сквозного отверстия обе апертуры и внутренняя стенка, для вырезки её полный открытый контур.',
'openings':'Вся именованная группа отверстий с собственными костными краями и сквозными просветами, а не случайный дефект сетки.',
'large_opening':'Весь непрерывный костный ободок большого отверстия, обе его стороны и открытый сквозной просвет.',
'channel':'Обе апертуры, непрерывный просвет между ними и полный макроскопический костный контур стенки по ходу канала; нерв или одна апертура недостаточны.',
'cavity':'Все ограничивающие костные стенки полости и её сообщения; отдельный объём воздуха не заменяет проверку костных стенок.',
'septum':'Вся костная перегородка от одного прикреплённого края до другого и обе её поверхности внутри полости.',
'fissure':'Вся щель, обе её ограничивающие стороны и концы с непрерывно прослеживаемым просветом.',
'landmark':'Однозначное положение именованного точечного или регионального ориентира на видимом полном окружающем контуре; отдельная сегментация не нужна.',
'corner':'Сам угол и оба сходящихся костных края на данной стороне, без подмены отражением другой кости.',
'condyle':'Весь костный мыщелок, контур суставной поверхности и переход к основанию.',
'compound_relief':'Все составные крупные элементы именованного рельефного комплекса и их взаимные переходы.',
'variant_suture':'Реальный образец с присутствующим вариантом: весь шов с обоими концами; проекция типичного места недостаточна.',
'variant_bone':'Реальный образец с присутствующим вариантом: вся добавочная кость и отделяющий её шов.',
'variant_process':'Реальный образец с присутствующим вариантом: весь выступ от основания до верхушки.',
'variant_opening':'Реальный образец с присутствующим вариантом: обе апертуры, полный край и сквозной просвет отверстия.',
'variant_channel':'Реальный образец с присутствующим вариантом: обе апертуры и непрерывные просвет и костные стенки канальца.',
'variant_plate':'Реальный образец с присутствующим вариантом: вся дополнительная костная пластинка и её свободные/прикреплённые края.'}

def build():
    render=read('build_head/cranial_extent/views.json')
    for s in render['sources'].values(): assert sha(s['file']) == s['sha256'], 'Changed source: re-render and re-review'
    # Screenshot files are development evidence; published metadata preserves their
    # hashes. Missing cache does not silently trigger a fabricated new review.
    for v in render['records']:
        if (ROOT/v['image']).exists(): assert sha(v['image']) == v['sha256']
    evidence=read('research/head-evidence.json')['bone_features']
    text=(ROOT/'site/pins-head.js').read_text(encoding='utf-8')
    pins=json.loads(text.split('push(...',1)[1].rsplit(');',1)[0])
    manual={}
    for bone,table in TABLES.items():
        manual[bone]={}
        for line in table.strip().splitlines():
            n,status,kind,views,observation=line.split('|')
            manual[bone][int(n)]={'status':{'C':'complete','P':'partial','N':'not_demonstrated'}[status], 'kind':kind,'views':views.split(','),'observation':observation}
    records={(v['source'],v['bone'],v['view']):v for v in render['records']}
    rows=[]
    for p in pins:
        bone=p['b']; base=bone.replace('_right','').replace('_left','')
        if base not in TABLES or p.get('t')!='ta': continue
        code=p['c']; a=manual[base][int(code.split('.')[-1])]; assessments=[]
        for source in ['bp','z']:
            status=a['status']; obs=a['observation']; viewnames=[]
            for view in a['views']:
                if view=='med': view='left' if bone.endswith('_right') else 'right'
                if view=='lat': view='right' if bone.endswith('_right') else 'left'
                viewnames.append(view)
            views=[]
            for view in viewnames:
                r=records[source,bone,view]
                views.append({**r['camera'],'screenshot':r['image'],'screenshotSha256':r['sha256'],'parts':[bone],'cut':None})
            # Explicit differences observed on the actual second mesh.
            if source=='z' and code=='A02.1.05.038':
                status='partial';obs='Обе апертуры остистых отверстий выделены собственными маркерами Z; полный внутренний костный контур по окружности пока не проверен.'
            if source=='z' and code=='A02.1.05.053':
                status='partial';obs='Передние апертуры обоих крыловидных каналов подтверждены на Z; непрерывный ход со всеми костными стенками не продемонстрирован.'
            if source=='z' and code=='A02.1.05.051':
                status='complete';obs='Оба крючковидных окончания Z прослеживаются от медиальных пластинок через узкую шейку к загнутым свободным верхушкам в заднем, нижнем и двух боковых видах; малые борозды проверяются отдельно.'
            if source=='z' and code=='A02.1.07.006':
                status='partial';obs='Срединная пластинка Z имеет прямолинейные незамкнутые дефекты исходных авторских операций; полный неповреждённый костный лист не подтверждён.'
            limitations=[] if status=='complete' else ['Не выполнен весь критерий: '+CRITERIA[a['kind']]]
            if source=='z': limitations.append('Z-Anatomy использует производную BodyParts3D; это не независимый образец или второе независимое подтверждение.')
            assessments.append({'source':source,'mesh':render['sources'][source]['file'],'meshSha256':render['sources'][source]['sha256'],'node':'b|'+bone,'status':status,'confirmedExtent':obs,'limitations':limitations,'views':views,'viewer':{'mode':'main' if source=='bp' else 'z','part':bone,'view':{k:views[0][k] for k in ['d','up']}}})
        best=min((x['status'] for x in assessments),key=['complete','partial','not_demonstrated','not_inspected'].index)
        rows.append({'bone':bone,'code':code,'side':'right' if bone.endswith('_right') else 'left' if bone.endswith('_left') else 'unpaired','ru':p['ru'],'lat':p['lat'],'originalLocalization':p['loc'],'requiredExtent':{'type':a['kind'],'criterion':CRITERIA[a['kind']],'topographicScope':evidence[code]['x'],'pairedFeaturesOnUnpairedBone':'Для парного образования внутри непарной кости требуется подтверждение обеих сторон; одна сторона не закрывает запись.' if not bone.startswith('parietal') else None},'assessments':assessments,'bestStatus':best,'completeFeatureGeometry':best=='complete','refs':evidence[code]['refs'],'reviewMethod':'Ручной осмотр фактических сеток в ортографических и косых ракурсах, сопоставление с отдельными анатомическими источниками. Исходная категория маркера не использована как доказательство целой формы.','scope':'macroscopic_source_feature_extent'})
    assert len(rows)==172 and len({(r['bone'],r['code']) for r in rows})==172
    assert all(len(r['refs'])>=2 and all(x.get('locator') for x in r['refs']) for r in rows)
    sources={**render['sources']}
    sources['bp'].update(license='CC BY-SA 2.1 Japan',provenance='BodyParts3D 3.0, исходные кости без дополнительного упрощения; сборка build_head/head_hi.glb.',url='https://dbarchive.biosciencedbc.jp/en/bodyparts3d/')
    sources['z'].update(license='CC BY-SA 4.0',provenance='Z-Anatomy с атрибуцией BodyParts3D; авторские операции по provenance.json, смена осей, без дополнительного восстановления анатомии.',url='https://github.com/Z-Anatomy/Models-of-human-anatomy')
    # Existing independent native evidence remains limited to its measured scope.
    native=read('pins_head/cranial-native-features.json')['markers']
    for r in rows:
        r['additionalNativeEvidence']=[{'source':'z','marker':m['id'],'scope':m['scope'],'modelNote':m['modelNote'],'viewer':{'mode':'z','part':m['b'],'marker':m['id'],'view':m['view']},'completeFeatureGeometry':False} for m in native if m['c']==r['code']]
    channel=read('site/skull-cranial-channels.json'); c=channel['structures'][0]
    sourcefile='site/'+channel['file']; assert sha(sourcefile)==channel['sha256']
    sources['halle']={'file':sourcefile,'sha256':channel['sha256'],'license':channel['license'],'url':channel['sourceUrl'],'provenance':channel['attribution']}
    r=next(r for r in rows if r['code']=='A02.1.04.016')
    r['assessments'].append({'source':'halle','mesh':sourcefile,'meshSha256':channel['sha256'],'node':c['node'],'status':'partial','confirmedExtent':'На независимом препарате прослежен непрерывный просвет между обеими апертурами по исходной КТ; обе апертуры и окружающий костный блок визуально проверены.','limitations':[c['modelNote'],'Этот канал не зарегистрирован на BodyParts3D; сторона не присвоена. Полная окружность стенки не везде замкнута в исходной маске.'], 'views':[{'screenshot':f,'screenshotSha256':sha(f)} for f in c['evidence']['review_images']],'viewer':{'mode':'cranial_channels','source':'halle','part':c['id'],'view':c['view']},'evidenceFile':'research/cranial-channel-review.json','continuousLumenConfirmed':True,'completeWallConfirmed':False})
    r['bestStatus']='partial';r['completeFeatureGeometry']=False
    # Targeted views of the independent complete Halle specimen. These are not a
    # claim that all 172 structures have undergone a native CT review.
    halle=read('build_head/cranial_extent/halle-views.json')
    hs=halle['sources']['halle'];assert sha(hs['file'])==hs['sha256']
    sources['halle']['additionalModels']=[hs]
    hv={v['view']:v for v in halle['records']}
    targeted={
      'A02.1.03.007':(['ant','sup','oblique_front'],'На лобной области Halle отдельный непрерывный метопический шов не различен; поперечный подготовительный распил не является этим швом.'),
      'A02.1.03.024':(['ant','oblique_front','xminus','xplus'],'Медиальные стенки глазниц в опубликованной поверхности местами фрагментированы; самостоятельная блоковая ость с целой формой не подтверждена.'),
      'A02.1.04.013':(['post','sup','oblique_back'],'Ламбдовидная область и верхняя чешуя осмотрены; отделённая собственным швом целая межтеменная кость не продемонстрирована.'),
      'A02.1.04.035':(['inf','xminus','xplus'],'Нижняя яремная/мыщелковая область видна, но отдельный полный парасосцевидный отросток надёжно не выделен.'),
      'A02.1.05.008':(['internal_base','internal_base_oblique'],'Область седла на внутреннем виде видна, однако полная самостоятельная форма среднего наклонённого отростка не отделена от неровной и местами незамкнутой поверхности сегментации.'),
      'A02.1.05.037':(['internal_base','inf'],'Около овальных отверстий есть множественные мелкие дефекты опубликованной оболочки; никакой из них не принят за венозное отверстие без отдельной проверки КТ и обоих выходов.'),
      'A02.1.05.039':(['internal_base','inf'],'Мелкий каменистый каналец и обе его апертуры в области основания не выделены; отдельный дефект оболочки не считается доказательством канальца.'),
      'A02.1.05.054':(['inf','oblique_front','xminus','xplus'],'Крыловидная область осмотрена; самостоятельный крыловидно-остистый отросток с целой формой надёжно не выделен.'),
      'A02.1.07.012':(['ant','internal_base','inf'],'Внутренняя решётчатая область и её тонкие пластинки частично разрушены в опубликованной поверхности; отдельная целая наивысшая раковина не подтверждена.')}
    for r in rows:
        if r['code'] not in targeted:continue
        names,obs=targeted[r['code']];views=[]
        for name in names:
            v=hv[name]
            if (ROOT/v['image']).exists():assert sha(v['image'])==v['sha256']
            views.append({**v['camera'],'screenshot':v['image'],'screenshotSha256':v['sha256'],'parts':['microct_surface']})
        camera=views[0];viewer={'mode':'microct','part':'microct_surface','view':{k:camera[k] for k in ['d','up']}}
        if camera.get('cut'):
            viewer['cut']={'plane':'axial','value':(.105-.005625000223517418)/(.17212501168251038-.005625000223517418),'reverse':True}
            viewer['view'].update(target=[.074,.0635,.1085],distance=.34)
        r['assessments'].append({'source':'halle','mesh':hs['file'],'meshSha256':hs['sha256'],'node':'microct_surface (viewer aggregate)','status':'not_demonstrated','confirmedExtent':obs,'limitations':['Это целевой региональный осмотр поверхности с выборкой 0,25 мм и упрощением; отсутствие различимого образования не доказывает отсутствие в исходном препарате.','Сторона тела по исходному LPS не присваивается; xminus/xplus — направления координат, не стороны тела.','Срез удаляет часть оболочки для обзора и не добавляет отсутствующую стенку.'],'views':views,'viewer':viewer})
    for r in rows:
        if r['code'] in ['A02.1.07.002','A02.1.07.005','A02.1.07.014','A02.1.05.006','A02.1.05.023','A02.1.04.028']:
            changed=r['code'] in ['A02.1.07.002','A02.1.07.014']
